```tsx
// A
function LastSeen() {
  return <span>{Math.round((Date.now() - lastVisit) / 60000)} min ago</span>;
}

// B
function Greeting() {
  const [name, setName] = useState<string | null>(null);
  useEffect(() => setName(localStorage.getItem("name")), []);
  return <p>{name ? `Hi, ${name}` : "Hi!"}</p>;
}

// C
function Cart() {
  const count = typeof window !== "undefined"
    ? JSON.parse(localStorage.getItem("cart") ?? "[]").length
    : 0;
  return <span>{count > 0 ? <Badge n={count} /> : null}</span>;
}
```
All three are client components inside a server-rendered page. A user with 3 items in localStorage cart and a stored name loads the page 4 seconds after the server rendered it.

